use Asaas\Laravel\Models\Notification;

class NotificationServiceTest extends ServiceTestCase
{
    public function test_update(): void
    {
        $this->fakeResponse(['id' => 'not_wuGp97JeCr7G', 'object' => 'notification', 'customer' => 'cus_000005219613', 'enabled' => true, 'emailEnabledForProvider' => true, 'smsEnabledForProvider' => true, 'emailEnabledForCustomer' => true, 'smsEnabledForCustomer' => true, 'phoneCallEnabledForCustomer' => false, 'whatsappEnabledForCustomer' => false]);

        $result = asaas()->notification->update('id_1', []);

        $this->assertRequestSent('PUT', '/v3/notifications/id_1');
        $this->assertInstanceOf(Notification::class, $result);
    }

    public function test_update_batch(): void
    {
        $this->fakeResponse(['notifications' => [['id' => 'not_wuGp97JeCr7G', 'object' => 'notification', 'customer' => 'cus_000005219613', 'enabled' => true]]]);

        $result = asaas()->notification->updateBatch(['customer' => 'cus_000005219613']);

        $this->assertRequestSent('PUT', '/v3/notifications/batch', [], ['customer' => 'cus_000005219613']);
        $this->assertInstanceOf(GenericResource::class, $result);
    }

    public function test_update_batch_rejects_missing_required_fields(): void
    {
        $this->assertValidationRejected(fn () => asaas()->notification->updateBatch([]), ['customer']);
    }
